// Reload refetches the object from the database
// using the primary keys with an executor.
func (o *AuthAttempt) Reload(ctx context.Context, exec boil.ContextExecutor) error {
	ret, err := FindAuthAttempt(ctx, exec, o.TenantID, o.Subject, o.Kind)
	if err != nil {
		return err
	}

	*o = *ret
	return nil
}

// ReloadAll refetches every row with matching primary key column values
// and overwrites the original object slice with the newly updated slice.
func (o *AuthAttemptSlice) ReloadAll(ctx context.Context, exec boil.ContextExecutor) error {
	if o == nil || len(*o) == 0 {
		return nil
	}

	slice := AuthAttemptSlice{}
	var args []any
	for _, obj := range *o {
		pkeyArgs := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(obj)), authAttemptPrimaryKeyMapping)
		args = append(args, pkeyArgs...)
	}

	sql := "SELECT \"auth_attempts\".* FROM \"auth_attempts\" WHERE " +
		strmangle.WhereClauseRepeated(string(dialect.LQ), string(dialect.RQ), 1, authAttemptPrimaryKeyColumns, len(*o))

	q := queries.Raw(sql, args...)

	err := q.Bind(ctx, exec, &slice)
	if err != nil {
		return errors.Wrap(err, "dbpostgres: unable to reload all in AuthAttemptSlice")
	}

	*o = slice

	return nil
}

// AuthAttemptExists checks if the AuthAttempt row exists.
func AuthAttemptExists(ctx context.Context, exec boil.ContextExecutor, tenantID string, subject string, kind string) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from \"auth_attempts\" where \"tenant_id\"=$1 AND \"subject\"=$2 AND \"kind\"=$3 limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, tenantID, subject, kind)
	}
	row := exec.QueryRowContext(ctx, sql, tenantID, subject, kind)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "dbpostgres: unable to check if auth_attempts exists")
	}

	return exists, nil
}

// Exists checks if the AuthAttempt row exists.
func (o *AuthAttempt) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return AuthAttemptExists(ctx, exec, o.TenantID, o.Subject, o.Kind)
}
